    function classifyReflectionContext(text, token) {
        const raw = String(text || ""); const i = raw.indexOf(String(token));
        if (i < 0) return { context:"not-found", encoding:"none", snippet:"" };
        const before = raw.slice(Math.max(0,i-420),i);
        const after = raw.slice(i+String(token).length,i+String(token).length+420);
        const win = before + String(token) + after;
        const htmlEntity = /&(?:lt|gt|quot|#x?[0-9a-f]+);/i.test(win);
        const script = /<script\b[^>]*>[\s\S]{0,500}$/i.test(before);
        const style = /<style\b[^>]*>[\s\S]{0,500}$/i.test(before) || /\bstyle\s*=\s*["'][^"']*$/i.test(before);
        const attr = /\b(?:href|src|action|formaction|srcdoc|value|title|alt|id|class|name|style)\s*=\s*["'][^"']*$/i.test(before);
        const textNode = />[^<>]{0,500}$/s.test(before) && /^[^<>]{0,500}</s.test(after);
        let context="raw-response";
        if (script) context="script"; else if (style) context="style"; else if (attr) context="html-attribute"; else if (textNode) context="html-text";
        if (/\b(?:href|src|action|formaction)\s*=\s*["'][^"']*$/i.test(before)) context="url-attribute";
        let encoding="raw";
        if (htmlEntity) encoding="html-entity"; else if (/%3c|%3e|%22|%27/i.test(win)) encoding="url-encoded";
        else if (/\\x(?:22|27|3c|3e)|\\u00(?:22|27|3c|3e)/i.test(win)) encoding="js-escaped";
        return { context, encoding, snippet: short(win,900) };
    }
    function countMarker(text, marker) {
        const raw=String(text||""); if(!marker) return 0;
        let n=0, at=0; while((at=raw.indexOf(marker,at))>=0){n++;at+=marker.length;} return n;
    }
    async function activeDeepReflectionTestForParam(param) {
        const page=session.pages[param.pageId]; if(!page||!safeActiveTarget(page.url)) return;
        const base=new URL(page.url), baseline=await activeGet(base.href);
        const token=canaryToken("DEEP");
        const canary=`XSSS_${token}_<xss-sentinel>__</xss-sentinel>_"'_`;
        const u=new URL(base.href); u.searchParams.set(param.name,canary);
        const result=await activeGet(u.href);
        const rawHit=result.text.includes(canary);
        const encodedHit=result.text.includes(encodeURIComponent(canary)) || result.text.includes(canary.replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#39;"));
        const ctx=classifyReflectionContext(result.text,canary);
        const markerCount=countMarker(result.text,token), reflected=rawHit||encodedHit||markerCount>0;
        const interesting=reflected && ctx.context!=="not-found";
        recordActiveTest({
            url:u.href,category:"deep-reflection",name:"Context-aware controlled canary",method:"GET",
            parameter:param.name,canary:token,status:result.status===0?"REQUEST-FAILED":(reflected?(interesting?"REFLECTED-CONTEXT":"REFLECTED"):"NO-REFLECTION"),
            responseStatus:result.status,reflected,contentType:result.type,context:ctx.context,encoding:ctx.encoding,
            baselineStatus:baseline.status,baselineLength:baseline.text.length,testLength:result.text.length,
            lengthDelta:result.text.length-baseline.text.length,markerCount,confidence:interesting?"HIGH":"MEDIUM",
            evidence:reflected?ctx.snippet:`Baseline HTTP ${baseline.status}; probe HTTP ${result.status}; marker count ${markerCount}; no canary representation observed.`
        });
        if(interesting) addFinding({
            type:"active-reflection-context",severity:(ctx.context==="html-attribute"||ctx.context==="url-attribute"||ctx.context==="script")?"MEDIUM":"LOW",
            confidence:"HIGH",status:"VALIDATED-CONTEXT",title:`Controlled canary reflected in ${ctx.context}: ${param.name}`,
            source:`query:${param.name}`,evidence:ctx.snippet,evidenceKey:`deep-reflection|${param.pageId}|${param.name}|${ctx.context}`,
            description:`A non-executable canary was observed in a ${ctx.context} response context. This confirms reflection/context, not script execution.`
        });
    }
    async function activeDOMPathProbe() {
        if(!authorized()||!settings.deepActiveTests||!history?.pushState) return;
        const original=location.href, u=new URL(original), token=canaryToken("PATH");
        const segment=`xss-sentinel-${token}-<xss-sentinel></xss-sentinel>`;
        const probeURL=new URL((u.pathname.replace(/\/$/,"")||"")+"/"+encodeURIComponent(segment),u.origin);
        const oldSource=state.sourceRegistry.get("location.pathname");
        const probeId=uid("pathprobe");
        state.activeProbe={id:probeId,source:"location.pathname",token,startedAt:Date.now()};
        let observed=false, customNode=false; const beforeCount=document.querySelectorAll("xss-sentinel").length;
        try {
            state.activePhase="dom-path probe"; refreshUI();
            state.sourceRegistry.set("location.pathname",probeURL.pathname);
            history.pushState({ ...(history.state||{}), __xssSentinelProbe:true },"",probeURL.href);
            await sleep(180); try{window.dispatchEvent(new PopStateEvent("popstate",{state:history.state}))}catch{}
            await sleep(550);
            const afterCount=document.querySelectorAll("xss-sentinel").length;
            customNode=afterCount>beforeCount;
            const bodyHTML=document.documentElement?.outerHTML||"";
            observed=bodyHTML.includes(token)||bodyHTML.includes("xss-sentinel-"+token);
            const flowHit=Object.values(session.pages||{}).some(p=>(p.flows||[]).some(f=>f.probeId===probeId&&f.source==="location.pathname"&&/innerHTML|insertAdjacentHTML/i.test(f.sink)));
            const hit=flowHit||customNode||observed;
            recordActiveTest({
                url:probeURL.href,category:"dom-path",name:"Controlled pathname→DOM probe",method:"BROWSER",parameter:"location.pathname",canary:token,
                status:customNode?"DOM-CANARY-OBSERVED":(observed?"PATH-MARKER-OBSERVED":(flowHit?"FLOW-OBSERVED":"NO-DOM-EFFECT")),
                responseStatus:200,reflected:hit,context:customNode?"html-element":(flowHit?"runtime-sink":"route"),encoding:"url-encoded",
                markerCount:observed?1:0,confidence:customNode?"HIGH":(hit?"MEDIUM":"LOW"),
                evidence:customNode?"Harmless <xss-sentinel> custom element observed after the controlled pathname transition.":observed?"The controlled pathname marker became observable in the live document.":flowHit?"Runtime source→sink flow was observed during the controlled pathname transition; no executable payload was used.":"No controlled pathname marker or DOM effect was observed."
            });
            if(customNode||(flowHit&&observed)) addFinding({
                type:"dom-path-probe",severity:customNode?"HIGH":"MEDIUM",confidence:"HIGH",status:"CONTROLLED-PROBE",
                title:"Controlled pathname reached an HTML DOM sink",source:"location.pathname",sink:"innerHTML",
                evidence:customNode?"Harmless custom element observed after controlled pathname transition.":"Runtime flow plus route marker observation.",
                evidenceKey:"dom-path-probe|pathname|innerHTML",description:"Controlled, non-executable path data reached the live DOM. Manual review is required to determine whether attacker-controlled data can become executable HTML/JS."
            });
        }catch(e){recordActiveTest({url:original,category:"dom-path",name:"Controlled pathname→DOM probe",status:"ERROR",responseStatus:0,evidence:String(e?.message||e)})}
        finally{
            try{history.replaceState(history.state,"",original)}catch{}
            try{window.dispatchEvent(new PopStateEvent("popstate",{state:history.state}))}catch{}
            if(oldSource===undefined)state.sourceRegistry.delete("location.pathname");else state.sourceRegistry.set("location.pathname",oldSource);
            state.activeProbe=null;
            await sleep(120);
        }
    }

    function executionProofPayload(token) {
        const safeToken = String(token).replace(/[^a-z0-9_-]/gi, "");
        return '"><img src=x onerror="document.documentElement.setAttribute(&quot;data-xss-sentinel-proof&quot;,&quot;' + safeToken + '&quot;)">';
    }

    async function runBrowserExecutionProof() {
        if (!authorized() || !settings.labMode) {
            alert("Önce GLOBAL ACTIVE ve LAB ACTIVE açılmalı.");
            return;
        }
        const targets = activeParamTargets().slice(0, 8);
        if (!targets.length) {
            recordActiveTest({
                category:"execution-proof",
                name:"Browser execution proof",
                status:"NO-TARGETS",
                responseStatus:0,
                evidence:"No safe same-origin query parameters were available."
            });
            return;
        }

        state.activePhase = "execution-proof";
        refreshUI();

        for (const param of targets) {
            if (state.stopping) break;
            const page = session.pages[param.pageId];
            if (!page || !safeActiveTarget(page.url)) continue;

            const token = canaryToken("EXEC");
            const payload = executionProofPayload(token);
            const target = new URL(page.url);
            target.searchParams.set(param.name, payload);

            const frame = document.createElement("iframe");
            frame.setAttribute(UI, "1");
            Object.assign(frame.style, {
                position:"fixed",
                width:"3px",
                height:"3px",
                left:"-10000px",
                top:"-10000px",
                border:"0",
                opacity:"0"
            });

            let finished = false;
            const finish = (status, evidence, confidence, context) => {
                if (finished) return;
                finished = true;
                clearTimeout(timer);
                try { frame.remove(); } catch {}
                recordActiveTest({
                    url:target.href,
                    category:"execution-proof",
                    name:"Controlled browser execution proof",
                    method:"GET",
                    parameter:param.name,
                    canary:token,
                    status,
                    responseStatus:200,
                    reflected:status === "EXECUTED",
                    context:context || "browser",
                    confidence:confidence || "LOW",
                    evidence
                });
                if (status === "EXECUTED") {
                    addFinding({
                        type:"active-execution-proof",
                        severity:"HIGH",
                        confidence:"HIGH",
                        status:"VALIDATED-EXECUTION",
                        title:"Controlled canary executed in browser",
                        source:"query:" + param.name,
                        sink:"HTML event handler",
                        evidence,
                        evidenceKey:"execution-proof|" + page.id + "|" + param.name,
                        description:"A harmless canary caused only a DOM marker to be written inside a same-origin test frame. No credentials or external data were accessed."
                    });
                }
            };

            const timer = setTimeout(() => {
                finish("TIMEOUT",
                    "The browser test frame did not produce an execution marker within the observation window.",
                    "LOW",
                    "browser");
            }, 3000);

            frame.onload = () => {
                try {
                    const root = frame.contentDocument?.documentElement;
                    const proof = root?.getAttribute("data-xss-sentinel-proof");
                    const html = root?.outerHTML || "";

                    if (proof === token) {
                        finish(
                            "EXECUTED",
                            "The canary executed and set data-xss-sentinel-proof on the isolated same-origin test document.",
                            "HIGH",
                            "event-handler"
                        );
                    } else if (html.includes(token)) {
                        finish(
                            "REFLECTED-NOT-EXECUTED",
                            "The controlled canary reached the loaded document, but the execution marker was not created.",
                            "MEDIUM",
                            "dom"
                        );
                    } else {
                        finish(
                            "LOADED-NOT-EXECUTED",
                            "The test document loaded, but neither the execution marker nor the canary token was observed.",
                            "LOW",
                            "browser"
                        );
                    }
                } catch (e) {
                    finish("INSPECT-FAILED", String(e?.message || e), "LOW", "browser");
                }
            };

            frame.onerror = () => {
                finish("NAVIGATION-FAILED",
                    "The browser test frame failed to load.",
                    "LOW",
                    "browser");
            };

            document.documentElement.appendChild(frame);
            frame.src = target.href;

            await new Promise(resolve => {
                const until = Date.now() + 3400;
                const poll = () => finished || Date.now() >= until ? resolve() : setTimeout(poll, 80);
                poll();
            });
        }

        state.activePhase = "finished";
        forceSave();
        refreshUI();
    }

    function activeSafeFormTargets() {
        const targets = [];
        for (const form of session.forms || []) {
            if (!form || String(form.method).toUpperCase() !== "GET" || !form.action || !safeActiveTarget(form.action)) continue;
            for (const field of form.fields || []) if (field?.name && !field.sensitive) targets.push({form,field});
        }
        return targets.slice(0,25);
    }
    async function activeGETFormTest(target) {
        const token = canaryToken("XSSS");
        const u = new URL(target.form.action);
        u.searchParams.set(target.field.name, token);
        const result = await activeGet(u.href);
        const context = extractReflectionContext(result.text, token);
        recordActiveTest({
            url:u.href, category:"form-reflection", name:"GET form canary reflection", method:"GET",
            parameter:target.field.name, canary:token,
            status:result.status ? (context ? "REFLECTED" : "NO-REFLECTION") : "REQUEST-FAILED",
            responseStatus:result.status, reflected:!!context,
            evidence:context || `GET form target returned HTTP ${result.status}; no scanner canary reflection observed.`
        });
        if (context) addFinding({
            type:"active-form-reflection", severity:"MEDIUM", confidence:"HIGH", status:"VALIDATED-REFLECTION",
            title:`GET form value reflected: ${target.field.name}`, source:`form:${target.field.name}`,
            evidence:context, evidenceKey:`active-form|${target.form.action}|${target.field.name}`,
            description:"A controlled canary was reflected by a GET form target. No JavaScript payload was executed."
        });
    }
    async function activeEndpointSmokeTest() {
        const endpoints = uniq((session.endpoints || []).map(x => x.url).filter(Boolean).filter(safeActiveTarget), x=>x)
            .slice(0, clamp(Number(settings.maxActiveEndpoints) || 20, 1, 50));
        if (!endpoints.length) {
            recordActiveTest({category:"endpoint-smoke", name:"Endpoint smoke phase", status:"NO-TARGETS", responseStatus:0, evidence:"No safe same-origin endpoint target was available."});
            return;
        }
        for (let i = 0; i < endpoints.length; i++) {
            const url = endpoints[i];
            state.activePhase = `endpoint-smoke ${i+1}/${endpoints.length}`;
            refreshUI();
            const token = canaryToken("EP");
            const u = safeURL(url);
            if (!u) continue;
            u.searchParams.set("__xss_sentinel", token);
            let result;
            try {
                result = await activeGet(u.href);
            } catch (e) {
                result = {status:0,text:"",type:"",error:String(e?.message || e)};
            }
            const context = extractReflectionContext(result.text, token);
            recordActiveTest({
                url:u.href, category:"endpoint-smoke", name:"Endpoint controlled canary smoke test", method:"GET",
                canary:token, status:result.status ? (context ? "REFLECTED" : "RESPONDED") : "REQUEST-FAILED",
                responseStatus:result.status, reflected:!!context,
                evidence:context || `HTTP ${result.status || 0}; content-type ${result.type || "unknown"}; ${result.error || "completed"}.`
            });
            if (context) addFinding({
                type:"active-endpoint-reflection", severity:"MEDIUM", confidence:"HIGH", status:"VALIDATED-REFLECTION",
                title:`Endpoint reflects a scanner canary: ${u.pathname}`, evidence:context,
                evidenceKey:`active-endpoint|${u.pathname}`,
                description:"A harmless query canary was reflected by an endpoint response."
            });
            await sleep(120);
        }
    }
    async function activeRedirectObservation() {
        const candidates = (session.parameters || [])
            .filter(p => p?.name && !p.sensitive && /(?:redirect|return|next|continue|callback|dest|destination|target)/i.test(p.name))
            .slice(0,10);
        for (const p of candidates) {
            const page = session.pages[p.pageId];
            if (!page) continue;
            const u = new URL(page.url);
            const token = canaryToken("REDIR");
            const destination = `https://xss-sentinel.invalid/${token}`;
            u.searchParams.set(p.name, destination);
            try {
                const r = await fetch(u.href,{method:"GET",credentials:"include",redirect:"manual",cache:"no-store",headers:{Accept:"text/html,*/*;q=0.1"}});
                const redirected = r.type === "opaqueredirect";
                recordActiveTest({
                    url:u.href, category:"redirect-observation", name:"Redirect parameter observation", method:"GET",
                    parameter:p.name, canary:token, status:redirected ? "REDIRECT-OBSERVED" : "NO-OPAQUE-REDIRECT",
                    responseStatus:r.status,
                    evidence:redirected ? "Browser reported an opaque redirect for the controlled destination." : `Browser returned response type ${r.type}; no opaque redirect observed.`
                });
                if (redirected) addFinding({
                    type:"active-open-redirect-signal", severity:"MEDIUM", confidence:"MEDIUM", status:"POTENTIAL",
                    title:`Redirect-like parameter accepted a controlled external destination: ${p.name}`,
                    evidence:`Destination: ${destination}`, evidenceKey:`active-redirect|${p.pageId}|${p.name}`,
                    description:"The browser observed an opaque redirect after a controlled external destination was supplied. Confirm manually before treating this as an open redirect."
                });
            } catch (e) {
                recordActiveTest({url:u.href,category:"redirect-observation",name:"Redirect parameter observation",method:"GET",parameter:p.name,canary:token,status:"REQUEST-FAILED",responseStatus:0,evidence:String(e?.message || e)});
            }
        }
    }
    function runActiveWorkflowPlan() {
        return [
            "1. Authorize the exact host.",
            "2. Crawl same-origin routes and assets.",
            "3. Map query/form parameters and endpoint shapes.",
            "4. Run harmless reflection canaries against non-sensitive GET parameters.",
            "5. Run context-aware deep reflection tests and classify response context/encoding.",
            "6. Correlate reflected canaries with runtime source→sink observations.",
            "7. Run a controlled pathname→DOM probe for the observed location.pathname → HTML sink flow.",
            "8. Smoke-test discovered safe GET endpoints with a dedicated scanner marker.",
            "9. Observe redirect-like parameters with a controlled external destination.",
            "10. Preserve bounded evidence, baselines, context and confidence for manual confirmation."
        ];
    }
    async function runActiveLab() {
        if (!authorized()) { alert("Önce GLOBAL ACTIVE ile hedef hostu yetkilendir."); return; }
        if (state.activeRunning) return;
        state.activeRunning=true; state.stopping=false; state.activeStartedAt=iso();
        settings.labMode=true; settings.activeCanaryTests=true; GM_setValue(SETTINGS_KEY,settings); refreshUI();
        recordActiveTest({category:"workflow",name:"LAB ACTIVE deep workflow started",status:"STARTED",evidence:runActiveWorkflowPlan().join(" | ")});
        try {
            state.activePhase="reflection"; refreshUI();
            const params=activeParamTargets();
            if(!params.length) recordActiveTest({category:"reflection",name:"Query reflection phase",status:"NO-TARGETS",responseStatus:0,evidence:"No safe non-sensitive query parameters were available across the discovered pages."});
            else for(let i=0;i<params.length;i++){
                if(state.stopping)break; state.activePhase=`reflection ${i+1}/${params.length}`; refreshUI();
                try{await activeReflectionTestForParam(params[i])}catch(e){recordActiveTest({category:"reflection",name:"Query reflection test",status:"ERROR",parameter:params[i].name,responseStatus:0,evidence:String(e?.message||e)})}
                await sleep(140);
            }
            if(!state.stopping&&settings.deepActiveTests){
                state.activePhase="deep-reflection"; refreshUI();
                const deepParams=params.slice(0,clamp(Number(settings.maxDeepParams)||20,1,50));
                if(!deepParams.length) recordActiveTest({category:"deep-reflection",name:"Deep reflection phase",status:"NO-TARGETS",responseStatus:0,evidence:"No safe query parameters available for context-aware testing."});
                else for(let i=0;i<deepParams.length;i++){
                    if(state.stopping)break; state.activePhase=`deep-reflection ${i+1}/${deepParams.length}`; refreshUI();
                    try{await activeDeepReflectionTestForParam(deepParams[i])}catch(e){recordActiveTest({category:"deep-reflection",name:"Context-aware canary test",status:"ERROR",parameter:deepParams[i].name,responseStatus:0,evidence:String(e?.message||e)})}
                    await sleep(180);
                }
                if(!state.stopping)try{await activeDOMPathProbe()}catch(e){recordActiveTest({category:"dom-path",name:"Controlled pathname→DOM probe",status:"ERROR",responseStatus:0,evidence:String(e?.message||e)})}
            }
            state.activePhase="forms"; refreshUI();
            const forms=activeSafeFormTargets();
            if(!forms.length) recordActiveTest({category:"form-reflection",name:"GET form phase",status:"NO-TARGETS",responseStatus:0,evidence:"No safe GET form controls were available. Non-GET forms remain manual-review targets."});
            else for(let i=0;i<forms.length;i++){
                if(state.stopping)break; state.activePhase=`forms ${i+1}/${forms.length}`; refreshUI();
                try{await activeGETFormTest(forms[i])}catch(e){recordActiveTest({category:"form-reflection",name:"GET form test",status:"ERROR",parameter:forms[i].field?.name,responseStatus:0,evidence:String(e?.message||e)})}
                await sleep(140);
            }
            if(!state.stopping){state.activePhase="endpoints";refreshUI();try{await activeEndpointSmokeTest()}catch(e){recordActiveTest({category:"endpoint-smoke",name:"Endpoint phase",status:"ERROR",responseStatus:0,evidence:String(e?.message||e)})}}
            if(!state.stopping){state.activePhase="redirects";refreshUI();try{await activeRedirectObservation()}catch(e){recordActiveTest({category:"redirect-observation",name:"Redirect phase",status:"ERROR",responseStatus:0,evidence:String(e?.message||e)})}}
        }finally{
            state.activePhase="finished";
            recordActiveTest({category:"workflow",name:"LAB ACTIVE deep workflow finished",status:state.stopping?"STOPPED":"COMPLETED",evidence:`Deep active tests recorded: ${session.activeTests.length}.`});
            state.activeRunning=false;state.activeStartedAt=null;forceSave();refreshUI();
        }
    }
    function toggleLabMode() {
        if (!authorized()) { alert("Önce GLOBAL ACTIVE ile hostu yetkilendir."); return; }
        settings.labMode = !settings.labMode;
        GM_setValue(SETTINGS_KEY, settings);
        refreshUI();
        if (settings.labMode && !state.activeRunning) void runActiveLab();
    }

    async function runIntel() {
        const deps = uniq(session.dependencies.filter(x => x.name && x.version), x => `${x.name}|${x.version}`);
        if (!deps.length) { alert("Versioni yakalanmış dependency yok. Önce scan çalıştır."); return; }

        let kev = {};
        try {
            const raw = await gmGET("https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json", 20000);
            const data = JSON.parse(raw || "{}");
            for (const x of data.vulnerabilities || []) kev[String(x.cveID).toUpperCase()] = x;
        } catch (e) { console.debug("XSS Sentinel KEV", e); }

        let processed = 0;
        for (const dep of deps.slice(0, 25)) {
            processed++;
            try {
                const [osv, github] = await Promise.allSettled([
                    queryOSV(dep.name, dep.version),
                    queryGitHubAdvisories(dep.name, dep.version)
                ]);

                const vulns = osv.status === "fulfilled" ? (osv.value?.vulns || []) : [];
                for (const v of vulns) {
                    const aliases = cveAliases(v);
                    const kevMatches = aliases.filter(c => kev[c]);
                    recordIntel({
                        key: `osv|${dep.name}|${dep.version}|${v.id}`,
                        source: "OSV",
                        id: v.id,
                        package: dep.name,
                        version: dep.version,
                        summary: v.summary || "",
                        aliases,
                        kev: kevMatches.length > 0,
                        url: `https://osv.dev/vulnerability/${encodeURIComponent(v.id)}`,
                        at: iso()
                    });
                    addFinding({
                        type: kevMatches.length ? "intel-kev" : "intel-vulnerability",
                        severity: kevMatches.length ? "HIGH" : "INFO",
                        confidence: kevMatches.length ? "HIGH" : "MEDIUM",
                        title: kevMatches.length ? `${dep.name} ${dep.version} maps to CISA KEV` : `${dep.name} ${dep.version}: ${v.id}`,
                        status: "INTEL",
                        evidence: `${v.id}${aliases.length ? ` | ${aliases.join(", ")}` : ""}`,
                        evidenceKey: `osv|${dep.name}|${dep.version}|${v.id}`,
                        description: kevMatches.length ? "Dependency intelligence matched a CVE present in CISA KEV." : "OSV matched a vulnerability record; applicability still depends on package/version context."
                    });

                    for (const cve of aliases.slice(0, 6)) {
                        let nvd = null, epss = null;
                        try { nvd = await queryNVD(cve); } catch (e) { console.debug("XSS Sentinel NVD", cve, e); }
                        try { epss = await queryEPSS(cve); } catch (e) { console.debug("XSS Sentinel EPSS", cve, e); }
                        const metric = epss?.data?.[0] || null;
                        const cvss = nvd?.vulnerabilities?.[0]?.cve?.metrics || {};
                        recordIntel({
                            key: `cve|${dep.name}|${dep.version}|${cve}`,
                            source: "NVD/EPSS",
                            cve,
                            package: dep.name,
                            version: dep.version,
                            kev: !!kev[cve],
                            epss: metric?.epss ?? null,
                            epssPercentile: metric?.percentile ?? null,
                            nvd: !!nvd?.vulnerabilities?.length,
                            cvssV31: cvss.cvssMetricV31?.[0]?.cvssData?.baseScore ?? null,
                            cvssV30: cvss.cvssMetricV30?.[0]?.cvssData?.baseScore ?? null,
                            url: `https://nvd.nist.gov/vuln/detail/${encodeURIComponent(cve)}`,
                            at: iso()
                        });
                    }
                }

                if (github.status === "fulfilled" && Array.isArray(github.value)) {
                    for (const a of github.value.slice(0, 20)) {
                        const cves = (a.cve_id ? [a.cve_id] : []).filter(x => /^CVE-\d{4}-\d+$/i.test(x)).map(x => x.toUpperCase());
                        recordIntel({
                            key: `github|${dep.name}|${dep.version}|${a.ghsa_id || a.cve_id || a.html_url}`,
                            source: "GitHub Advisory",
                            id: a.ghsa_id || a.cve_id || null,
                            package: dep.name,
                            version: dep.version,
                            severity: a.severity || null,
                            cves,
                            kev: cves.some(c => !!kev[c]),
                            summary: a.summary || "",
                            url: a.html_url || `https://github.com/advisories?query=${encodeURIComponent(dep.name)}`,
                            at: iso()
                        });
                    }
                }
            } catch (e) {
                recordIntel({ key: `error|${dep.name}|${dep.version}`, source: "intel-error", package: dep.name, version: dep.version, error: String(e?.message || e), at: iso() });
            }
            if (processed % 3 === 0) { forceSave(); refreshUI(); }
            await sleep(250);
        }
        session.intelligence = uniq(session.intelligence, x => x.key);
        forceSave(); refreshUI();
    }

    function exportJSON() { forceSave(); download(`xss-sentinel-${Date.now()}.json`, JSON.stringify({ version: VERSION, generatedAt: iso(), settings, session, runtime: { flows: state.runtimeFlows } }, null, 2), "application/json"); }
    function exportFindings() {
        const rows = [["at", "page", "severity", "confidence", "status", "type", "title", "source", "sink", "description", "evidence"]];
        for (const f of session.findings) rows.push([f.at, session.pages[f.pageId]?.url || "", f.severity, f.confidence, f.status, f.type, f.title, f.source || "", f.sink || "", f.description, f.evidence]);
        download("xss-sentinel-findings.csv", rows.map(r => r.map(csv).join(",")).join("\n"), "text/csv");
    }
    function exportPages() {
        const rows = [["url", "status", "httpStatus", "contentType", "title", "endpoints", "forms", "params", "technologies", "dependencies", "findings"]];
        for (const p of Object.values(session.pages)) rows.push([p.url, p.status, p.httpStatus || "", p.contentType || "", p.title, p.endpoints.length, p.forms.length, p.params.length, p.technologies.length, p.dependencies.length, p.findings.length]);
        download("xss-sentinel-pages.csv", rows.map(r => r.map(csv).join(",")).join("\n"), "text/csv");
    }
    function exportEndpoints() {
        const rows = [["url", "source", "kind", "at"]];
        for (const e of session.endpoints) rows.push([e.url, e.source, e.kind, e.at]);
        download("xss-sentinel-endpoints.csv", rows.map(r => r.map(csv).join(",")).join("\n"), "text/csv");
    }
    function resetSession() { stopAll(); session = newSession(); state.currentPageId = null; forceSave(); scanLivePage(); refreshUI(); }

    function button(label, fn, primary = false) {
        const b = document.createElement("button");
        b.textContent = label; b.onclick = fn;
        Object.assign(b.style, { all: "initial", display: "inline-block", margin: "3px", padding: "7px 10px", border: "1px solid #3d4854", borderRadius: "6px", background: primary ? "#214f37" : "#182029", color: "#eaf0f6", cursor: "pointer", font: "12px ui-monospace,monospace" });
        return b;
    }
    function sec(title) {
        const d = document.createElement("section");
        const h = document.createElement("div"); h.textContent = title; h.style.fontWeight = "700"; h.style.marginBottom = "6px"; d.appendChild(h); d.style.marginTop = "10px"; return d;
    }
    function refreshUI() {
        const d = state.dashboard; if (!d) return;
        d.replaceChildren();
        const head = document.createElement("div"); head.style.display = "flex"; head.style.justifyContent = "space-between";
        const t = document.createElement("strong"); t.textContent = `XSS Sentinel ${VERSION}`; head.appendChild(t);
        head.appendChild(button("×", () => d.style.display = "none")); d.appendChild(head);

        const g = sec("GLOBAL CONTROL");
        const mode = document.createElement("div"); mode.textContent = authorized() ? "● GLOBAL ACTIVE" : "○ GLOBAL PASSIVE"; mode.style.fontWeight = "700"; g.appendChild(mode);
        g.append(`Host: ${location.hostname}`, document.createElement("br"));
        g.append(`Scope: ${settings.sameOriginOnly ? "same-origin" : "broader"} | Crawler: ${settings.crawler ? "ON" : "OFF"}`, document.createElement("br"));
        g.appendChild(button(authorized() ? "GLOBAL ACTIVE OFF" : "GLOBAL ACTIVE ON", toggleActive, authorized()));
        g.appendChild(button(state.running ? "STOP ALL" : "START GLOBAL SCAN", state.running ? stopAll : () => void startScan(), true));
        g.appendChild(button(settings.paused ? "RESUME" : "PAUSE", () => { settings.paused = !settings.paused; GM_setValue(SETTINGS_KEY, settings); refreshUI(); }));
        d.appendChild(g);

        g.appendChild(button(settings.labMode ? "LAB ACTIVE OFF" : "LAB ACTIVE ON", toggleLabMode, settings.labMode));
        g.appendChild(button("RUN ACTIVE LAB TESTS", () => void runActiveLab(), settings.labMode));
        g.appendChild(button("BROWSER EXECUTION PROOF", () => void runBrowserExecutionProof(), settings.labMode));
        const plan = document.createElement("div");
        plan.style.marginTop = "6px";
        plan.style.opacity = "0.85";
        plan.textContent = state.activeRunning
            ? `ACTIVE RUNNING | phase=${state.activePhase}`
            : (settings.labMode ? "Controlled canaries: ON | destructive payloads: OFF | GET-only automatic validation" : "Lab mode OFF");
        g.appendChild(plan);

        const s = sec("STATUS");
        const st = session.stats;
        [
            `Pages ${st.pages} | Queue ${state.queue.length} | Crawling ${state.processing.size} | Crawled ${st.crawled} | Failed ${st.failed}`,
            `Endpoints ${st.endpoints} | Forms ${st.forms} | Parameters ${st.parameters}`,
            `Findings ${st.findings} | Runtime Flows ${st.flows}`,
            `Technologies ${st.technologies} | Dependencies ${st.dependencies} | Intel ${st.intelligence} | ActiveTests ${st.activeTests || 0} | Phase ${state.activePhase}`
        ].forEach(x => s.append(x, document.createElement("br")));
        d.appendChild(s);

        const psec = sec(`PAGES (${Object.keys(session.pages).length})`);
        Object.values(session.pages).slice(-35).reverse().forEach(p => { const row = document.createElement("div"); row.textContent = `[${p.status}] ${p.url} ${p.httpStatus ? `(${p.httpStatus})` : ""}`; row.style.margin = "3px 0"; psec.appendChild(row); });
        d.appendChild(psec);

        const qsec = sec(`QUEUE (${state.queue.length})`);
        state.queue.slice(0, 35).forEach(q => { const row = document.createElement("div"); row.textContent = `[${q.reason}] ${q.url}`; qsec.appendChild(row); });
        if (!state.queue.length) qsec.append("Queue empty.");
        d.appendChild(qsec);

        const fsec = sec(`FINDINGS (${session.findings.length})`);
        session.findings.slice(-25).reverse().forEach(f => { const row = document.createElement("div"); row.textContent = `[${f.severity}] ${f.title} | ${f.type} | ${f.confidence}`; Object.assign(row.style, { padding: "5px", margin: "3px 0", border: "1px solid #29323b", borderRadius: "5px" }); fsec.appendChild(row); });
        d.appendChild(fsec);

        const esec = sec(`ENDPOINTS (${session.endpoints.length})`);
        session.endpoints.slice(-30).reverse().forEach(e => esec.append(e.url, document.createElement("br")));
        d.appendChild(esec);

        const techRollup = uniq(session.technologies, x => x.name);
        const tsec = sec(`TECHNOLOGIES (${techRollup.length})`);
        techRollup.slice(-30).forEach(t => {
            const count = session.technologies.filter(x => x.name === t.name).length;
            tsec.append(`${t.name} [${t.confidence}] pages=${count}`, document.createElement("br"));
        });
        d.appendChild(tsec);

        const dsec = sec(`DEPENDENCIES (${session.dependencies.length})`);
        uniq(session.dependencies, x => `${x.name}|${x.version}|${x.url}`).slice(-30).forEach(x => dsec.append(`${x.name} ${x.version || "?"}`, document.createElement("br")));
        d.appendChild(dsec);

        const atsec = sec(`ACTIVE TEST RESULTS (${session.activeTests?.length || 0})`);
        (session.activeTests || []).slice(-20).reverse().forEach(x => {
            const row = document.createElement("div");
            row.textContent = `[${x.status}] ${x.category} | ${x.parameter || x.url} | HTTP ${x.responseStatus ?? "-"}${x.context ? ` | ${x.context}` : ""}${x.encoding ? ` | ${x.encoding}` : ""}`;
            row.style.padding = "4px";
            row.style.borderBottom = "1px solid #222a31";
            atsec.appendChild(row);
        });
        d.appendChild(atsec);

        const a = sec("ACTIONS");
        a.appendChild(button("CURRENT PAGE SCAN", scanLivePage));
        a.appendChild(button("RUN INTELLIGENCE", () => void runIntel()));
        a.appendChild(button("EXPORT JSON", exportJSON));
        a.appendChild(button("FINDINGS CSV", exportFindings));
        a.appendChild(button("PAGES CSV", exportPages));
        a.appendChild(button("ENDPOINTS CSV", exportEndpoints));
        a.appendChild(button("NEW SESSION", resetSession));
        d.appendChild(a);
    }
    function showDashboard() {
        if (!state.dashboard) initUI();
        if (state.dashboard) { state.dashboard.style.display = "block"; refreshUI(); }
    }

    function initUI() {
        if (state.dashboard) return;
        const d = document.createElement("div");
        d.setAttribute(UI, "1"); state.dashboard = d;
        Object.assign(d.style, { all: "initial", position: "fixed", right: "16px", bottom: "16px", width: "590px", maxHeight: "88vh", overflow: "auto", zIndex: "2147483647", padding: "14px", border: "1px solid #394552", borderRadius: "10px", background: "#0c1116", color: "#e7eef5", boxShadow: "0 20px 70px rgba(0,0,0,.6)", font: "12px ui-monospace,SFMono-Regular,Menlo,monospace", boxSizing: "border-box" });
        document.documentElement.appendChild(d); refreshUI();
    }
    function recomputeStats() {
        const pages = Object.values(session.pages);
        session.stats.pages = pages.length;
        session.stats.domains = new Set(pages.map(x => x.host)).size;
        session.stats.queued = state.queue.length;
        session.stats.crawling = state.processing.size;
        session.stats.crawled = pages.filter(x => x.status === "crawled").length;
        session.stats.failed = pages.filter(x => x.status === "request-failed").length;
        session.stats.endpoints = session.endpoints.length;
        session.stats.forms = session.forms.length;
        session.stats.parameters = session.parameters.length;
        session.stats.findings = session.findings.length;
        session.stats.flows = state.runtimeFlows.length;
        session.stats.technologies = uniq(session.technologies, x => x.name).length;
        session.stats.dependencies = uniq(session.dependencies, x => `${x.name}|${x.version}|${x.url}`).length;
        session.stats.intelligence = session.intelligence.length;
        session.stats.activeTests = session.activeTests?.length || 0;
    }

    window.XSSSentinel = { version: VERSION, start: startScan, stop: stopAll, toggle: toggleActive, lab: { toggle: toggleLabMode, run: runActiveLab, plan: runActiveWorkflowPlan, deep: activeDOMPathProbe, proof: runBrowserExecutionProof }, scan: scanLivePage, intel: runIntel, exportJSON, reset: resetSession, getState: () => ({ settings, session, running: state.running, queue: [...state.queue], activePhase: state.activePhase }) };

    GM_registerMenuCommand("XSS Sentinel — ACTIVE START/STOP", toggleActive);
    GM_registerMenuCommand("XSS Sentinel — START GLOBAL SCAN", () => void startScan());
    GM_registerMenuCommand("XSS Sentinel — STOP ALL", stopAll);
    GM_registerMenuCommand("XSS Sentinel — RUN INTELLIGENCE", () => void runIntel());
    GM_registerMenuCommand("XSS Sentinel — CURRENT PAGE SCAN", scanLivePage);
    GM_registerMenuCommand("XSS Sentinel — LAB ACTIVE ON/OFF", toggleLabMode);
    GM_registerMenuCommand("XSS Sentinel — RUN ACTIVE LAB TESTS", () => void runActiveLab());
    GM_registerMenuCommand("XSS Sentinel — SHOW DASHBOARD", showDashboard);
    GM_registerMenuCommand("XSS Sentinel — NEW SESSION", resetSession);
    GM_registerMenuCommand("XSS Sentinel — EXPORT JSON", exportJSON);

